//! agc_types.h — `agc_<enum>_name` / `agc_<enum>_from_name` for every enum.
//! The tables and exports are generated by build.rs from the headers; this
//! file holds what they share.

use std::ffi::{CStr, c_char};

use crate::bindings::agc_rc;
use crate::ffi::error::FfiError;
use crate::ffi::guard::guard;
use crate::ffi::translation::required_str;

/// The proto name of `v`, or "(unknown)" for a value the header does not name
/// (a C enum can hold any integer).
fn enum_name<T: PartialEq + Copy>(table: &[(T, &'static CStr)], v: T) -> *const c_char {
    table.iter().find(|(value, _)| *value == v).map_or(c"(unknown)", |(_, name)| name).as_ptr()
}

/// Looks `name` up in `table`. NULL arguments and unknown names are
/// `AGC_ERR_INVALID_ARGUMENT`; `*out` is written only on success.
///
/// # Safety
/// `name` is NULL or a NUL-terminated string; `out` is NULL or writable.
unsafe fn enum_from_name<T: Copy>(table: &[(T, &'static CStr)], name: *const c_char, out: *mut T) -> agc_rc {
    guard(|| {
        // SAFETY: name is NULL or a C string (this function's contract).
        let wanted = unsafe { required_str(name, "name") }?;
        if out.is_null() {
            return Err(FfiError::invalid("out must not be NULL"));
        }
        let (value, _) = table
            .iter()
            .find(|(_, n)| n.to_bytes() == wanted.as_bytes())
            .ok_or_else(|| FfiError::invalid(format!("{wanted} is not a name of this enum")))?;
        // SAFETY: out is non-null (checked above) and writable (contract).
        unsafe { out.write(*value) };
        Ok(())
    })
}

#[allow(non_upper_case_globals)] // bindgen's constant names
mod generated {
    // Only here: a glob of the bindings next to `pub use generated::*` would
    // make every generated name ambiguous with its bindgen declaration.
    use super::{enum_from_name, enum_name};
    use crate::bindings::*;
    include!(concat!(env!("OUT_DIR"), "/enum_helpers.rs"));
}
pub use generated::*;

#[cfg(test)]
mod tests {
    use std::ptr;

    use super::*;
    use crate::bindings::{
        AGC_ERR_INVALID_ARGUMENT, agc_aead_scope, agc_aead_scope_AGC_AEAD_SCOPE_DETERMINISTIC,
        agc_aead_scope_AGC_AEAD_SCOPE_STANDARD,
    };

    fn s(p: *const c_char) -> &'static str {
        // SAFETY: the name functions return static C strings.
        unsafe { CStr::from_ptr(p) }.to_str().unwrap()
    }

    #[test]
    fn every_enum_round_trips_every_value() {
        let mut enums = 0;
        generated::round_trip_all(&mut |base, len, ok| {
            enums += 1;
            assert!(len > 0, "{base} has no values");
            for i in 0..len {
                // Also proves names are unique: from_name returns the first match.
                assert!(ok(i), "{base}: value #{i} does not round-trip");
            }
        });
        assert_eq!(enums, 41, "one per *_name/*_from_name pair in agc_types.h");
    }

    #[test]
    fn names_are_the_proto_names() {
        assert_eq!(s(agc_aead_scope_name(agc_aead_scope_AGC_AEAD_SCOPE_STANDARD)), "AEAD_SCOPE_STANDARD");
        assert_eq!(s(agc_aead_scope_name(12345)), "(unknown)");
    }

    #[test]
    fn bad_from_name_input_is_rejected_and_out_untouched() {
        let mut out: agc_aead_scope = agc_aead_scope_AGC_AEAD_SCOPE_DETERMINISTIC;
        // SAFETY: NULL or static strings, and a live local.
        unsafe {
            assert_eq!(agc_aead_scope_from_name(ptr::null(), &mut out), AGC_ERR_INVALID_ARGUMENT);
            assert_eq!(agc_aead_scope_from_name(c"NOPE".as_ptr(), &mut out), AGC_ERR_INVALID_ARGUMENT);
            // A name of another enum is not a name of this one.
            assert_eq!(agc_aead_scope_from_name(c"MAC_SCOPE_STANDARD".as_ptr(), &mut out), AGC_ERR_INVALID_ARGUMENT);
            assert_eq!(agc_aead_scope_from_name(c"AEAD_SCOPE_STANDARD".as_ptr(), ptr::null_mut()), AGC_ERR_INVALID_ARGUMENT);
        }
        assert_eq!(out, agc_aead_scope_AGC_AEAD_SCOPE_DETERMINISTIC);
    }
}
